    'about.eyebrow': 'Our story',
    'about.title': 'Built by researchers, for researchers.',
    'about.p1':
      'GoPeptides was founded by a small group of biochemists frustrated by inconsistent peptide quality across the EU market. We launched in 2021 with one promise: every vial we ship matches its certificate.',
