    'about.geo.body':
      'GoPeptides is an Amsterdam-based supplier of HPLC-tested research peptides for laboratory use only. Orders include batch documentation (CoA) where available. Products are not medicines and must not be used in humans or animals. Primary sources: product pages, /labresults, /faq, and /llms.txt.',
