    // Science
    'science.eyebrow': 'The science',
    'science.title': 'Verification you can trace from vial to thesis.',
    'science.subtitle':
      'Every product we ship is independently analyzed. Here is what that actually means — the methodology, the documents, and the standards we hold to.',
    'science.hplc.title': 'HPLC Analysis',
    'science.hplc.p1':
      'High-Performance Liquid Chromatography (HPLC) is the gold standard for peptide purity verification. We partner with an ISO 17025-accredited lab that runs reverse-phase HPLC on every batch using a C18 column, water/acetonitrile gradient with 0.1% TFA.',
    'science.hplc.p2':
      'We report purity as the peak area of the target peptide divided by the total area of all peaks. Any batch below 99% is rejected.',
    'science.ms.title': 'Mass Spectrometry Confirmation',
    'science.ms.p':
      'HPLC alone tells us how clean a sample is, but not what is in it. We confirm identity using ESI mass spectrometry, comparing the observed mass against the theoretical mass of the target peptide. If the observed mass deviates by more than ±0.5 Da, the batch is rejected.',
    'science.coa.title': "What's in the Certificate of Analysis",
    'science.coa.l1': 'Product name, lot number, and date of analysis',
    'science.coa.l2': 'HPLC chromatogram trace as PDF',
    'science.coa.l3': 'Purity percentage (HPLC area %)',
    'science.coa.l4': 'Identity confirmation (MS-observed vs theoretical mass)',
    'science.coa.l5': 'Net peptide content (peptide vs counter-ion mass)',
