    'admin.settings.guides.payout.title': 'Bank Payout Connection Guide',
    'admin.settings.guides.payout.desc': 'To enable automatic payouts to your company\'s bank account, follow these steps:',
    'admin.settings.guides.payout.step1.title': 'Navigate to Gateway Provider Dashboard:',
    'admin.settings.guides.payout.step1.desc': 'Log in to your Stripe or primary credit card processor merchant dashboard.',
    'admin.settings.guides.payout.step2.title': 'Verify Account Details:',
    'admin.settings.guides.payout.step2.desc': 'Make sure your business identity, representative identity, and bank account credentials (IBAN/SWIFT) are fully validated under Payout Settings.',
    'admin.settings.guides.payout.step3.title': 'Set Payout Schedule:',
    'admin.settings.guides.payout.step3.desc': 'Choose your preferred payout frequency: daily automatic payouts, weekly, monthly, or manual trigger.',
    'admin.settings.guides.payout.step4.title': 'Configure webhook notifications:',
    'admin.settings.guides.payout.step4.desc': 'In the gateway settings, set up webhooks targeting the backend endpoint /api/payments/webhook with events like payout.created, payout.failed, and payout.paid to track payout state in our admin panel.',
    'admin.settings.guides.gateway.title': 'Custom Payment Gateway Integration',
    'admin.settings.guides.gateway.desc': 'Configure credentials and environment settings for payment processors (Credit Cards, NOWPayments):',
    'admin.settings.guides.gateway.bullet1.title': 'Stripe (Credit Cards / Bancontact / iDEAL):',
    'admin.settings.guides.gateway.bullet1.desc': 'Enter key credentials in your environment variables: STRIPE_SECRET_KEY, STRIPE_WEBHOOK_SECRET, and STRIPE_PUBLISHABLE_KEY. Restart the backend after updating env vars.',
    'admin.settings.guides.gateway.bullet2.title': 'NOWPayments (Crypto):',
    'admin.settings.guides.gateway.bullet2.desc': 'Enter your API key under the Integrations tab above. Toggle Sandbox Mode to run mock transactions using NOWPayments test environments.',
