    'why.tested.desc': 'Kwaliteit begint bij controle. Daarom laten we onze batches peptiden door een extern, onafhankelijk laboratorium analyseren met HPLC en massaspectrometrie. Deze twee methodes bevestigen zowel de zuiverheid als de exacte samenstelling, zodat je zeker weet wat je in huis haalt. Gecontroleerde kwaliteit, volledige transparantie — batch na batch.',
