    'quality.s1.title': 'Wat zijn peptiden?',
    'quality.s1.desc': 'Peptiden zijn korte ketens van aminozuren en vormen de bouwstenen van eiwitten. Ze komen van nature in het lichaam voor en functioneren als boodschappers in tal van biologische processen. Door deze signaalfunctie zijn peptiden uitgegroeid tot een breed bestudeerd onderwerp binnen de biochemie en het laboratoriumonderzoek.',
    'quality.s2.title': 'Peptiden bewaren: zo behoud je de stabiliteit',
    'quality.s2.desc': 'De houdbaarheid van peptiden hangt af van de juiste opslag. Gelyofiliseerde (gevriesdroogde) peptiden blijven kortdurend stabiel op kamertemperatuur, maar voor langdurige opslag bewaar je ze het best in de vriezer bij -20°C. Na reconstitutie horen ze gekoeld te worden bewaard, tussen 2-8°C. Bescherm de aminozuurketens altijd tegen licht, warmte en vocht, en houd de flacon goed afgesloten. De exacte houdbaarheid verschilt per peptide.',

