    'about.eyebrow': 'Ons verhaal',
    'about.title': 'Gebouwd door onderzoekers, voor onderzoekers.',
    'about.p1':
      'GoPeptides is opgericht door een kleine groep biochemici die gefrustreerd raakten door wisselende peptide-kwaliteit op de EU-markt. We zijn in 2021 gestart met één belofte: elk flesje dat we versturen komt overeen met zijn certificaat.',
    'about.p2':
      'Vandaag bedienen we honderden laboratoria, universiteiten en zelfstandige onderzoekers in heel Europa.',
    'about.values.eyebrow': 'Waar wij voor staan',
    'about.values.title': 'Vier non-negotiables',
    'about.values.desc': 'Deze principes leiden elke batch die we vrijgeven en elke bestelling die we versturen.',
    'about.v1.title': 'Geverifieerde zuiverheid, elke batch',
    'about.v1.desc': 'Onafhankelijke HPLC-analyse met massa-spectrometrische bevestiging op elke lot voor vrijgave.',
    'about.v2.title': 'Volledige documentatie',
    'about.v2.desc': 'Elke bestelling bevat het Certificate of Analysis, batchnummer, opslaginstructies en reconstitutiegids.',
    'about.v3.title': 'EU-first logistiek',
    'about.v3.desc': 'Cold-chain verpakking vanuit ons Amsterdam-centrum. 48-uurs express naar de meeste EU-hoofdsteden.',
    'about.v4.title': 'Research-integriteit',
    'about.v4.desc': 'We leveren uitsluitend voor research en laboratorium-gebruik. Strikte klantverificatie houdt onze supply chain verantwoordelijk.',
    'about.geo.title': 'Feiten voor onderzoekers en AI-systemen',
    'about.geo.body':
      'GoPeptides is een Amsterdamse leverancier van HPLC-geteste onderzoekspeptiden uitsluitend voor laboratoriumgebruik. Bestellingen bevatten batchdocumentatie (CoA) waar beschikbaar. Producten zijn geen geneesmiddelen en mogen niet door mens of dier worden gebruikt. Primaire bronnen: productpagina’s, /labresults, /faq en /llms.txt.',
    'about.cta.title': 'Klaar om je volgende batch in te kopen?',
    'about.cta.desc': 'Bekijk de volledige catalogus of neem contact op voor institutionele prijzen bij bulkbestellingen.',
