    'about.cta.talk': 'Praat met ons team',

    'science.eyebrow': 'De wetenschap',
    'science.title': 'Verificatie die je van flesje tot proefschrift kunt traceren.',
    'science.subtitle':
      'Elk product dat we versturen wordt onafhankelijk geanalyseerd. Hier lees je wat dat concreet betekent — de methodologie, de documenten en de standaarden die we hanteren.',
    'science.hplc.title': 'HPLC Analyse',
    'science.hplc.p1':
      'High-Performance Liquid Chromatography (HPLC) is de gouden standaard voor peptide-zuiverheidsverificatie. We werken samen met een ISO 17025-geaccrediteerd lab dat reverse-phase HPLC uitvoert op elke batch met een C18-kolom en water/acetonitril-gradiënt met 0.1% TFA.',
    'science.hplc.p2':
      'We rapporteren zuiverheid als het piekoppervlak van het doelpeptide gedeeld door het totale piekoppervlak. Elke batch onder 99% wordt afgewezen.',
    'science.ms.title': 'Massa-spectrometrische bevestiging',
    'science.ms.p':
      'HPLC alleen vertelt hoe schoon een sample is, maar niet wát erin zit. We bevestigen de identiteit met ESI-massaspectrometrie en vergelijken de waargenomen massa met de theoretische massa van het doelpeptide. Bij een afwijking groter dan ±0.5 Da wordt de batch afgewezen.',
    'science.coa.title': 'Wat zit er in het Certificate of Analysis',
