    'why.eyebrow': 'Warum GoPeptides?',
    'why.title': 'Der Standard in Qualität',
    'why.tested.title': 'Unabhängig auf Reinheit geprüft',
    'why.tested.desc': 'Qualität beginnt bei der Kontrolle. Wir lassen unsere Peptid-Chargen von einem externen, unabhängigen Labor mit HPLC und Massenspektrometrie analysieren. Diese beiden Methoden bestätigen sowohl die Reinheit als auch die genaue Zusammensetzung — kontrollierte Qualität, volle Transparenz, Charge für Charge.',
    'why.docs.title': 'Volle Transparenz via CoA',
    'why.docs.desc': 'Vertrauen entsteht durch Einblick. Bei jeder Bestellung erhältst du ein vollständiges Analysenzertifikat (CoA) mit Chromatogrammen und Chargennummer. So kannst du Reinheit und Herkunft deiner Peptide selbst nachlesen — keine Versprechen, nur harte Daten.',
    'why.logistics.title': 'Schnelle Lieferung aus den Niederlanden',
    'why.logistics.desc': 'Schnelligkeit ohne Aufwand. Unsere Peptide lagern in einem niederländischen Lager, sodass deine Bestellung schnell bearbeitet und versandt wird. Keine langen Wartezeiten, keine Unsicherheit — zuverlässige Lieferung, nah bei dir.',
    'why.tested.cta': 'Peptide ansehen',
    'why.docs.cta': 'Dokumentation ansehen',
    'why.logistics.cta': 'Bestellung starten',

    // Quality promise (homepage)
    'quality.eyebrow': 'Unser Versprechen',
    'quality.title': 'Auf Qualität gebaut',
    'quality.s1.title': 'Was sind Peptide?',
    'quality.s1.desc': 'Peptide sind kurze Ketten von Aminosäuren und bilden die Bausteine von Proteinen. Sie kommen natürlich im Körper vor und fungieren als Botenstoffe in zahlreichen biologischen Prozessen. Aufgrund dieser Signalfunktion sind Peptide zu einem weit erforschten Thema in der Biochemie und Laborforschung geworden.',
    'quality.s2.title': 'Peptide lagern: so erhältst du die Stabilität',
    'quality.s2.desc': 'Die Haltbarkeit von Peptiden hängt von der richtigen Lagerung ab. Lyophilisierte (gefriergetrocknete) Peptide bleiben kurzfristig bei Raumtemperatur stabil, aber für die Langzeitlagerung bewahrst du sie am besten im Gefrierschrank bei -20°C. Nach der Rekonstitution sollten sie gekühlt bei 2–8°C gelagert werden. Schütze die Aminosäureketten immer vor Licht, Wärme und Feuchtigkeit und halte das Fläschchen gut verschlossen.',

