    'about.eyebrow': 'Unsere Geschichte',
    'about.title': 'Gebaut von Forschern, für Forscher.',
    'about.p1':
      'GoPeptides wurde von einer kleinen Gruppe von Biochemikern gegründet, die frustriert von inkonsistenter Peptidqualität auf dem EU-Markt waren. Wir starteten 2021 mit einem Versprechen: Jedes Fläschchen, das wir versenden, entspricht seinem Zertifikat.',
    'about.p2':
      'Heute beliefern wir Hunderte von Labors, Universitäten und unabhängigen Forschern in ganz Europa.',
    'about.values.eyebrow': 'Wofür wir stehen',
    'about.values.title': 'Vier Grundsätze',
    'about.values.desc': 'Diese Prinzipien leiten jede Charge, die wir freigeben, und jede Bestellung, die wir versenden.',
    'about.v1.title': 'Verifizierte Reinheit, jede Charge',
    'about.v1.desc': 'Unabhängige HPLC-Analyse mit Massenspektrometrie-Bestätigung bei jeder Charge vor der Freigabe.',
    'about.v2.title': 'Vollständige Dokumentation',
    'about.v2.desc': 'Jede Bestellung enthält das Analysezertifikat, Chargennummer, Lagerungsanweisungen und Rekonstituierungsleitfaden.',
    'about.v3.title': 'EU-First Logistik',
    'about.v3.desc': 'Kaltkettenverpackung aus unserem Amsterdam-Standort. 48-Stunden-Express in die meisten EU-Hauptstädte.',
    'about.v4.title': 'Forschungsintegrität',
    'about.v4.desc': 'Wir liefern ausschließlich für Forschungs- und Laborzwecke. Strenge Kundenverifizierung hält unsere Lieferkette verantwortlich.',
    'about.geo.title': 'Fakten fuer Forscher und KI-Systeme',
    'about.geo.body':
      'GoPeptides ist ein Amsterdamer Anbieter HPLC-gepruefter Forschungspeptide ausschliesslich fuer den Laborgebrauch. Bestellungen enthalten Chargendokumentation (CoA), sofern verfuegbar. Produkte sind keine Arzneimittel und duerfen nicht an Mensch oder Tier verabreicht werden. Primaerquellen: Produktseiten, /labresults, /faq und /llms.txt.',
    'about.cta.title': 'Bereit, die nächste Charge zu beziehen?',
    'about.cta.desc': 'Den vollständigen Katalog durchsuchen oder für institutionelle Preise bei Großbestellungen kontaktieren.',
    'about.cta.browse': 'Katalog durchsuchen',
    'about.cta.talk': 'Unser Team kontaktieren',

    'science.eyebrow': 'Die Wissenschaft',
    'science.title': 'Verifizierung, die Sie vom Fläschchen bis zur Dissertation zurückverfolgen können.',
    'science.subtitle':
      'Jedes Produkt, das wir versenden, wird unabhängig analysiert. Hier erfahren Sie, was das konkret bedeutet — Methodik, Dokumente und unsere Standards.',
    'science.hplc.title': 'HPLC-Analyse',
    'science.hplc.p1':
      'High-Performance Liquid Chromatography (HPLC) ist der Goldstandard für Peptid-Reinheitsverifizierung. Wir arbeiten mit einem ISO 17025-akkreditierten Labor, das Reverse-Phase-HPLC auf jede Charge mit einer C18-Säule anwendet.',
    'science.hplc.p2':
      'Wir berichten die Reinheit als Peakfläche des Zielpeptids geteilt durch die Gesamtfläche aller Peaks. Jede Charge unter 99% wird abgelehnt.',
    'science.ms.title': 'Massenspektrometrie-Bestätigung',
    'science.ms.p':
      'HPLC allein sagt, wie sauber eine Probe ist, nicht was darin enthalten ist. Wir bestätigen die Identität per ESI-Massenspektrometrie, indem wir die beobachtete Masse mit der theoretischen Masse vergleichen.',
    'science.coa.title': 'Was ist im Analysezertifikat enthalten',
    'science.coa.l1': 'Produktname, Chargennummer und Analysedatum',
    'science.coa.l2': 'HPLC-Chromatogramm als PDF',
    'science.coa.l3': 'Reinheitsprozentzahl (HPLC Flächen %)',
    'science.coa.l4': 'Identitätsbestätigung (MS-beobachtet vs. theoretische Masse)',
    'science.coa.l5': 'Netto-Peptidgehalt (Peptid vs. Gegenionen-Masse)',
    'science.coa.l6': 'Lagerungs- und Rekonstituierungsrichtlinien',
    'science.coa.l7': 'Autorisierte Unterschriften des ausstellenden Labors',
    'science.storage.title': 'Lagerung & Rekonstituierung',
    'science.storage.p':
      'Wir versenden Peptide lyophilisiert in Bernsteinglasfläschchen, versiegelt unter Inertgas. Unten allgemeine Richtlinien — produktspezifische Details liegen jeder Bestellung bei:',
    'science.storage.lyo': 'Lyophilisierte Lagerung',
